fn char_at(cs: List[Str], pos: Int) -> Str {
  return cs.get_or(pos, "")
}

fn in_set(allowed: Str, c: Str) -> Bool {
  return (not c.is_empty()) and allowed.contains(c)
}

fn text_of(cs: List[Str], from: Int, to: Int) -> Str {
  return cs.slice(from, to).join("")
}

fn scan_ident(cs: List[Str], pos: Int) -> Int {
  if in_set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_", char_at(cs, pos)) {
    return scan_ident(cs, pos + 1)
  }
  return pos
}

fn scan_digits(cs: List[Str], pos: Int) -> Int {
  if in_set("0123456789", char_at(cs, pos)) {
    return scan_digits(cs, pos + 1)
  }
  return pos
}

fn scan_str(cs: List[Str], i: Int) -> Int {
  if i >= cs.len() {
    return -1
  }
  let c = char_at(cs, i)
  if c == "\"" {
    return i + 1
  }
  if c == "\\" {
    return scan_str(cs, i + 2)
  }
  return scan_str(cs, i + 1)
}

fn lex(cs: List[Str], pos: Int, acc: List[Str]) -> Result[List[Str], Str] {
  if pos >= cs.len() {
    return Ok(acc)
  }
  let c = char_at(cs, pos)
  if c == " " or c == "\t" or c == "\n" or c == "\r" {
    return lex(cs: cs, pos: pos + 1, acc: acc)
  }
  if in_set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_", c) {
    let end = scan_ident(cs, pos)
    return lex(cs: cs, pos: end, acc: acc.push(text_of(cs: cs, from: pos, to: end)))
  }
  if in_set("0123456789", c) {
    let end = scan_digits(cs, pos)
    return lex(cs: cs, pos: end, acc: acc.push(text_of(cs: cs, from: pos, to: end)))
  }
  if c == "\"" {
    let end = scan_str(cs, pos + 1)
    if end < 0 {
      return Err("unterminated string")
    }
    return lex(cs: cs, pos: end, acc: acc.push(text_of(cs: cs, from: pos, to: end)))
  }
  let two_ops: List[Str] = ["==", "!=", "<=", ">=", "->"]
  let two = text_of(cs: cs, from: pos, to: (pos + 2).min(cs.len()))
  if two_ops.contains(two) {
    return lex(cs: cs, pos: pos + 2, acc: acc.push(two))
  }
  if in_set("+-*/<>=(){},;", c) {
    return lex(cs: cs, pos: pos + 1, acc: acc.push(c))
  }
  return Err("unexpected " + c)
}

pub fn tokens(src: Str) -> Result[List[Str], Str] {
  let cs = src.chars()
  let none: List[Str] = []
  return lex(cs: cs, pos: 0, acc: none)
}
